import { EventEmitter } from 'node:events';

interface OrderPlaced { readonly orderId: string; readonly occurredOn: Date }
interface DomainEvents { 'order.placed': [OrderPlaced] }

class OrderBus extends EventEmitter<DomainEvents> {}

bus.on('order.placed', (e) => reserveStock(e.orderId));
bus.emit('order.placed', { orderId, occurredOn: new Date() });

type DomainEvent =
  | { kind: 'order.placed'; orderId: string; occurredOn: Date }
  | { kind: 'order.refunded'; orderId: string; cents: number };

type EventOf<K extends DomainEvent['kind']> = Extract<DomainEvent, { kind: K }>;

publish<K extends DomainEvent['kind']>(kind: K, event: EventOf<K>): void;

bus.subscribe('order.placed', (e) => reserveStock(e.orderId));
